import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:hive_flutter/hive_flutter.dart';
import 'core/theme/app_theme.dart';
import 'core/theme/theme_provider.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Hive.initFlutter();
  // Adapters will be generated by build_runner
  // Hive.registerAdapter(HabitModelAdapter());
  // Hive.registerAdapter(CompletionModelAdapter());

  runApp(const ProviderScope(child: StreaklyApp()));
}

class StreaklyApp extends ConsumerWidget {
  const StreaklyApp({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final themeMode = ref.watch(appThemeModeProvider);
    return MaterialApp.router(
      title: 'Streakly',
      theme: AppTheme.light(),
      darkTheme: AppTheme.dark(),
      themeMode: themeMode,
      routerConfig: AppRouter.router,
    );
  }
}

// Simple router stub to avoid build errors; will be expanded later
class AppRouter {
  static final router = _EmptyRouter().router;
}

class _EmptyRouter {
  final router = null;
}
